【図解】根切り時の注意
　項目｜内容｜理由
　機械掘削の残し代｜床付け面の上30から50cm★｜地盤の乱れ防止
　床付けの仕上げ｜平爪バケットまたは手掘り★｜同上
　雨天時の養生｜シート掛け・排水溝｜床付け面の軟弱化防止★
