━━━━━━━━━━━━━━━━━━━━━━
【図解】改良後の確認方法
　確認項目｜方法｜判定
　改良体の強度｜コアの一軸圧縮試験★｜設計基準強度以上
　改良範囲｜施工記録と位置測量｜設計どおりの配置
