　そこで、引張力がかかる位置に鉄の棒を入れる。これが鉄筋である。
　鉄筋は工場から定尺で届き、現場や加工場で切り、曲げ、組み立てる。
　曲げ方が甘いとコンクリートから抜け、きつすぎると鉄筋が折れる。
　だから折曲げ内法直径がミリ単位で決められている。

