　コンクリートを現場で型枠に流し込むのが在来工法だが、
　あらかじめ工場で部材の形に打っておき、現場では組み立てるだけにする方法がある。
　これがプレキャストコンクリート（PCa）工事である。
　工場は雨も風もなく、蒸気養生もできるので品質が安定し、
　現場の工期は劇的に短くなる。ただし接合部の施工が命になる。

━━━━━━━━━━━━━━━━━━━━━━
