　工法｜張付けモルタルを塗る面｜特徴
　密着張り（ヴィブラート工法）★｜下地面｜振動工具でたたき込む
　改良圧着張り★｜下地面とタイル裏面の両方｜接着性が高い
　改良積上げ張り★｜タイル裏面｜下から上へ積み上げる
